{
  "name": "BioShake 加热振荡器（微孔板）",
  "name_en": "BioShake Microplate Heater Shaker",
  "manufacturer": "QInstruments",
  "description": "BioShake 是用于微孔板的加热振荡一体化实验室设备，可在设定温度下对孔板进行振荡混匀，并可通过锁板机构固定孔板以防移位；常用于酶促反应、孵育、混匀、样品制备等流程。",
  "description_en": "BioShake is an integrated microplate heater shaker used to mix microplates by orbital shaking while controlling the plate temperature. It can clamp/lock the plate to prevent movement during shaking, and is commonly used for incubation, enzymatic reactions, mixing, and sample preparation workflows.",
  "actions": [
    {
      "action_name": "auto-setup",
      "description": "初始化设备（复位并回零/归位，使设备进入可运行状态）",
      "description_en": "Initialize the device (reset and home it to a ready-to-run state)"
    },
    {
      "action_name": "auto-reset",
      "description": "复位设备（用于从异常/卡死状态恢复）",
      "description_en": "Reset the device (recover from an error or stuck state)"
    },
    {
      "action_name": "auto-home",
      "description": "回零/归位设备到初始位置",
      "description_en": "Home the device to its reference position"
    },
    {
      "action_name": "auto-stop",
      "description": "停止设备当前运行（总体停止）",
      "description_en": "Stop the device (overall stop)"
    },
    {
      "action_name": "auto-shake",
      "description": "以设定速度（及加速度）开始振荡混匀",
      "description_en": "Start shaking at the specified speed (and acceleration)"
    },
    {
      "action_name": "auto-stop_shaking",
      "description": "停止振荡（可设定减速度）",
      "description_en": "Stop shaking (optionally with a specified deceleration)"
    },
    {
      "action_name": "auto-set_temperature",
      "description": "set 温度设定值（启动/维持温控）",
      "description_en": "set the temperature setpoint (start/maintain temperature control)"
    },
    {
      "action_name": "auto-get_current_temperature",
      "description": "get 当前温度",
      "description_en": "get the current temperature"
    },
    {
      "action_name": "auto-deactivate",
      "description": "停止温度控制（关闭加热/温控功能）",
      "description_en": "Deactivate temperature control (stop heating/temperature regulation)"
    },
    {
      "action_name": "auto-lock_plate",
      "description": "锁定/夹紧微孔板",
      "description_en": "Lock/clamp the microplate"
    },
    {
      "action_name": "auto-unlock_plate",
      "description": "解锁/松开微孔板",
      "description_en": "Unlock/release the microplate"
    },
    {
      "action_name": "auto-supports_locking",
      "description": "get 是否支持锁板功能",
      "description_en": "get whether plate locking is supported"
    },
    {
      "action_name": "auto-supports_active_cooling",
      "description": "get 是否支持主动制冷",
      "description_en": "get whether active cooling is supported"
    }
  ],
  "tag_hints": [
    "microplate heater shaker",
    "orbital shaking",
    "plate incubation",
    "temperature control",
    "microplate clamping/locking",
    "sample mixing"
  ]
}
